for a in [32]:
    for add in [0, 16, -16, 31, -31, 15, -15]:
        def f(s,m,add=add):
            return (s*32 + add)//m
        err=test_formula(f)
        if err<10:
            print(f"add {add} err {err}")

# Try (s*32)//(m+1) etc
for delta in [-1,0,1,2]:
    def f(s,m,delta=delta):
        return (s*32)//(m+delta)
    print(f"delta {delta} err {test_formula(f)}")

# Try (s-1)*32//m etc
def f1(s,m): return ((s-1)*32)//m if s>0 else 0
print(" (s-1)*32//m err", test_formula(f1))

def f2(s,m): return (s*32 -1)//m if s>0 else 0
print(" s*32-1 //m err", test_formula(f2))

def f3(s,m): return int(s*32/m - 0.5)
print(" s*32/m -0.5 err", test_formula(f3))

def f4(s,m): return int(math.floor(s*32/m - 0.5))
print(" floor(s*32/m -0.5) err", test_formula(f4))

# Try with rounding down then minus 1 if not max
def f5(s,m):
    v= s*32//m
    if s==m:
        return 32
    if v>0:
        return v-1
    else:
        return 0
print(" v-1 if not max err", test_formula(f5))

def f6(s,m):
    v= (s*32)//m
    if s!=m and v>0:
        # if s*32 % m ==0? then?
        if s*32 % m ==0:
            return v-1
        else:
            return v-1 if v>1 else v
    return v
print("f6 err", test_formula(f6))

# Try v = (s*32 + m//2)//m  # round
def f7(s,m):
    return (s*32 + m//2)//m
print("round err", test_formula(f7))

