#!/usr/bin/env python3
import os, sys, re, stat

VERSION="0.2.18"

def parse_size(s):
    m = re.match(r'^(\d+)([KMG])?$', s)
    if not m:
        return None
    num = int(m.group(1))
    suf = m.group(2)
    if suf == 'K':
        return num * 1024
    elif suf == 'M':
        return num * 1024*1024
    elif suf == 'G':
        return num * 1024*1024*1024
    else:
        return num

def format_size(sz, bytes_flag):
    if bytes_flag:
        return f"{sz} B"
    else:
        if sz < 1024:
            return f"{sz} B"
        elif sz < 1024*1024:
            return f"{sz/1024:.2f} KiB"
        elif sz < 1024*1024*1024:
            return f"{sz/(1024*1024):.2f} MiB"
        else:
            return f"{sz/(1024*1024*1024):.2f} GiB"

def get_file_size(path, use_blocks):
    try:
        st = os.lstat(path)
    except:
        return 0
    if use_blocks:
        try:
            return st.st_blocks * 512
        except AttributeError:
            return st.st_size
    else:
        return st.st_size

class Node:
    __slots__ = ('name','path','size','is_dir','children')
    def __init__(self, name, path, size, is_dir, children):
        self.name=name
        self.path=path
        self.size=size
        self.is_dir=is_dir
        self.children=children

def build_full_tree(path, exclude_set, no_hidden, files_only, use_blocks):
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        return None
    is_symlink = os.path.islink(path)
    mode = st.st_mode
    is_dir = stat.S_ISDIR(mode)
    if is_symlink:
        is_dir = False
    norm = os.path.normpath(path)
    if norm == ".":
        try:
            cwd = os.getcwd()
            name = os.path.basename(cwd) or cwd
        except:
            name = "."
    elif norm == "/":
        name = "/"
    else:
        name = os.path.basename(norm)
        if not name:
            name = norm
    if is_dir:
        dir_size = st.st_blocks*512 if use_blocks else st.st_size
        children = []
        total = dir_size
        try:
            with os.scandir(path) as it:
                for entry in it:
                    ename = entry.name
                    if no_hidden and ename.startswith('.'):
                        continue
                    if ename in exclude_set:
                        continue
                    try:
                        est = entry.stat(follow_symlinks=False)
                    except:
                        continue
                    e_is_symlink = entry.is_symlink()
                    e_is_dir = stat.S_ISDIR(est.st_mode)
                    if e_is_symlink:
                        e_is_dir = False
                    e_path = entry.path
                    if files_only:
                        if e_is_dir:
                            continue
                        sz = est.st_blocks*512 if use_blocks else est.st_size
                        child = Node(ename, e_path, sz, False, [])
                        children.append(child)
                        total += sz
                    else:
                        child = build_full_tree(e_path, exclude_set, no_hidden, files_only, use_blocks)
                        if child is not None:
                            children.append(child)
                            total += child.size
        except PermissionError:
            pass
        except OSError:
            pass
        return Node(name, path, total, True, children)
    else:
        sz = st.st_blocks*512 if use_blocks else st.st_size
        return Node(name, path, sz, False, [])

